"""Master test registry + release-gate machinery for Keyholder v0.2 (W08).

Normative sources: plan v3 SS4A G0-16 and final-check audit f17
(P-02 exception registry, P-05 master registry, P-06 artifact binding,
P-07 skip/mute/deletion rule, P-19 quarantine governance, P-20
exception transparency). CONTRACT SS13.6: W08 owns this file,
scripts/grep_gates.py, tests/test_gates.py, and the README Gate G0
table (with W20). No other module's logic is rewritten here.

What this file is
-----------------
1. ``REGISTRY_IDS``: the frozen, versioned list of every
   release-blocking test in this tree, as stable unittest IDs
   (``<module>.<Class>.<method>``) produced by the canonical runner::

       python3 -m unittest discover -s tests

   from the build root. A test added, removed, or renamed without a
   registry update FAILS the release gate by design (f17 P-05/P-07):
   deletion is not a way to pass, and an unregistered test is not a
   way to claim coverage.

2. Stop-ship classification (S1-S4, f17 Part 2). The S-class controls
   EXCEPTION ELIGIBILITY ONLY. Any failed or errored registry test
   fails the release gate, S-class or not. A test in an S-class can
   NEVER be excepted, skipped-with-paperwork, or quarantined past
   the gate (f17 P-02, P-19).

3. The exception registry (f17 P-02/P-20): versioned entries, one per
   test ID, mechanically validated. Rules enforced by
   :func:`validate_exception_registry`:
   - S1-S4 test IDs are rejected outright;
   - an entry must name a real registry test ID (excepting a deleted
     or nonexistent test is an error);
   - expiry is at most 30 days after grant, and an expired entry
     excuses nothing;
   - at most ONE renewal per test ID (initial + one renewal = at most
     two entries per test ID); a "new" entry for a test that already
     has one is a renewal and is counted as such (re-registration
     does not reset the cap);
   - approver and reviewer must be different named people, the
     reviewer signature must be present, and release-notes disclosure
     must be recorded.

4. Skip / mute / deletion definitions (f17 P-07, P-19):
   - SKIPPED: a unittest skip (including a class skip). Counts as a
     gate failure unless excused by a valid, unexpired, non-S1-S4
     exception entry.
   - MUTED: an expectedFailure (xfail) or an unexpectedSuccess.
     Same treatment as skipped: failure unless validly excepted.
   - QUARANTINED: not a separate outcome. Quarantine IS a skip with
     a nicer name: a quarantined test counts as skipped for gate
     purposes and may enter quarantine only via the exception
     registry (reviewer-signed, expiry <= 30 days). "Formally
     replaced" means a NEW registered test covering the same attack
     class, approved by the reviewer of record -- never a weaker
     test, a manual check, or a promise.
   - DELETED: a registry ID with no discovered test. Gate failure,
     listed by ID. A runner exit code of 0 is never sufficient
     evidence on its own.

5. Artifact binding (f17 P-06): a gate artifact (suite report, fuzz
   report, log-scan report, rebuild record) must carry the tested
   artifact's commit hash and build hash. The release gate refuses
   to sign unless the artifact's commit and build hash equal the
   artifact being shipped. Tests run on ``main``, on a debug build,
   or on a different commit satisfy no gate.

Honest limits of this machinery (read before claiming a gate passed)
--------------------------------------------------------------------
- The reviewer signature is PRESENCE-CHECKED only. No cryptographic
  reviewer signature exists in v0.2, and no independent reviewer of
  record has been appointed (that appointment is an OWNER decision,
  see the README Gate G0 table). Until one exists, solo-phase gates
  are self-attested, not independently verified (f17 residual risk 2).
- Commit binding is UNBOUND in this tree: there is no ``.git``
  repository here, so :func:`detect_commit` returns ``None`` and any
  release-gate evaluation with no expected commit FAILS with
  "commit unknown". That is the correct fail-closed behaviour, not a
  bug to work around by inventing a commit hash. The repo-dependent
  part (a real repo, a real commit, CI fetching the artifact and
  comparing hashes at sign time) can only close once a repo exists
  and the user approves it -- it is recorded OPEN, never closed here.
- CI wiring is W20-owned: ``.github/workflows/ci.yml`` does not yet
  call :func:`evaluate_release_gate` or ``scripts/grep_gates.py``.
  The gate functions are implemented and tested here; the workflow
  call that makes them bite in CI is OPEN (see README G0 table).
- Registry IDs are defined for the unittest runner above. pytest
  produces different IDs and is NOT the canonical runner for this
  gate (CONTRACT SS11).

Regeneration (when a test is legitimately added/removed/renamed)::

    python3 tests/test_registry.py --dump        # print current IDs
    python3 tests/test_registry.py --regenerate  # rewrite REGISTRY_IDS

Regeneration is deterministic (sorted IDs) and must be reviewed as a
diff: a regeneration that silently drops a hard test is exactly the
vacuous-suite bypass this registry exists to prevent. Gate-weakening
changes (registry edits, gate-function edits, workflow edits) require
reviewer-of-record approval once one exists (f17 P-10).

Only fake TEST-ONLY values appear in this file and its tests. No real
keys, tokens, or credentials anywhere.
"""

