# END REGISTRY

# ---------------------------------------------------------------------------
# Stop-ship classification (S1-S4)
# ---------------------------------------------------------------------------

# S1: the adversarial suite. In this tree that suite lives in
# tests/test_adversarial.py (its header names S1-S4 itself). Any test
# in that module is S1-class: a failure there stops the release, and
# it can never be excepted.
S1_MODULE = "test_adversarial"

# S2: any secret in any log in any test run. Keyword match on the
# method name, fail-closed: a test whose name says it guards a
# secret/scan/scrubber/pseudonym/tamper/truncation outcome is treated
# as S2. Three deny-tests are explicitly excluded because they test
# that a scope is DENIED, not that a secret stayed out of a log --
# misclassifying them would still be fail-closed, but it would be
# wrong, and this registry is auditable, so the exclusions are named.
S2_KEYWORDS = ("secret", "scanner", "scrubber", "pseudonym", "tamper", "truncation")
S2_EXCLUSIONS = frozenset({
    "test_import_refuses_ssh_keys_gists_secrets",
    "test_github_graphql_and_secrets_write_denied_not_forwarded",
    "test_07_secrets_and_graphql_denied_mock_unreached",
})

# S3: silent fallback to a raw key (config flags, env vars, bearer
# fallback, daemon-down fallback). One false positive is excluded:
# test_posix_scan_allows_attributeerror_fallback is about a platform
# scan tolerating an AttributeError, not about a credential fallback.
S3_KEYWORDS = ("fallback", "bare_bearer", "raw_key")
S3_EXCLUSIONS = frozenset({
    "test_posix_scan_allows_attributeerror_fallback",
})

# S4: approval spoofable in testing (spoofed prompts, replayed or
# forged approvals, approval bound to the wrong request, X11/dash-
# board approval paths that must never approve). Narrow on purpose:
# not every test with "approval" in its name is S4 -- only the
# spoof/replay/binding class named in f17 Part 2, S4.
S4_KEYWORDS = (
    "spoof",
    "replayed_approval",
    "approval_nonce",
    "stolen_control",
    "cannot_approve",
    "approval_bound",
    "forged",
    "x11",
)
S4_EXCLUSIONS = frozenset({
    # "forged" appears in a broker origin-decision test, not an
    # approval-spoof test.
    "test_broker_rejects_forged_origin_decision",
})


def _method_name(test_id: str) -> str:
    return test_id.rsplit(".", 1)[-1] if "." in test_id else test_id


def _module_name(test_id: str) -> str:
    parts = test_id.split(".")
    return parts[0] if parts else test_id


def classify_stop_ship(test_id: str) -> frozenset:
    """Return the stop-ship classes (subset of S1-S4) for a test ID.

    Empty set means: not a stop-ship test, so (and only so) it is
    eligible for the exception registry. The S-class never excuses
    a failure -- see the module docstring.
    """
    classes = set()
    method = _method_name(test_id)
    if _module_name(test_id) == S1_MODULE:
        classes.add("S1")
    if any(k in method for k in S2_KEYWORDS) and method not in S2_EXCLUSIONS:
        classes.add("S2")
    if any(k in method for k in S3_KEYWORDS) and method not in S3_EXCLUSIONS:
        classes.add("S3")
    if any(k in method for k in S4_KEYWORDS) and method not in S4_EXCLUSIONS:
        classes.add("S4")
    return frozenset(classes)


def stop_ship_ids() -> frozenset:
    """All registry IDs in at least one S-class (for audit reports)."""
    return frozenset(t for t in REGISTRY_IDS if classify_stop_ship(t))


# ---------------------------------------------------------------------------
# Exception registry
# ---------------------------------------------------------------------------

MAX_EXCEPTION_DAYS = 30
MAX_ENTRIES_PER_TEST = 2  # initial + at most one renewal


@dataclass
class ExceptionEntry:
    entry_id: str
    test_id: str
    reason: str
    risk: str
    compensating_control: str
    blast_radius: str
    approver_name: str
    reviewer_name: str
    reviewer_signature_present: bool
    granted: str  # ISO date, e.g. "2026-10-28"
    expiry: str  # ISO date
    renewal_count: int = 0
    renewal_of: str | None = None
    disclosed_in_release_notes: bool = False

    @classmethod
    def from_dict(cls, data: dict) -> "ExceptionEntry":
        return cls(
            entry_id=str(data.get("entry_id", "")),
            test_id=str(data.get("test_id", "")),
            reason=str(data.get("reason", "")),
            risk=str(data.get("risk", "")),
            compensating_control=str(data.get("compensating_control", "")),
            blast_radius=str(data.get("blast_radius", "")),
            approver_name=str(data.get("approver_name", "")),
            reviewer_name=str(data.get("reviewer_name", "")),
            reviewer_signature_present=bool(data.get("reviewer_signature_present", False)),
            granted=str(data.get("granted", "")),
            expiry=str(data.get("expiry", "")),
            renewal_count=int(data.get("renewal_count", 0)),
            renewal_of=data.get("renewal_of"),
            disclosed_in_release_notes=bool(data.get("disclosed_in_release_notes", False)),
        )


def _parse_date(value: str, errors: list, what: str):
    try:
        return date.fromisoformat(value)
    except (ValueError, TypeError):
        errors.append(f"exception {what}: date {value!r} is not ISO YYYY-MM-DD")
        return None


def validate_exception_registry(entries, today: date | None = None) -> list:
    """Mechanically validate exception entries. Empty list = valid.

    Every rule in the module docstring is enforced here; nothing is
    left to "CI enforces expiry" prose (f17 P-02). ``today`` defaults
    to the real current date; tests pass an explicit date.
    """
    if today is None:
        today = date.today()
    errors: list = []
    registry = set(REGISTRY_IDS)
    seen_entry_ids: set = set()
    by_test: dict = {}

    for entry in entries:
        tag = f"entry {entry.entry_id!r} (test {entry.test_id!r})"
        if not entry.entry_id:
            errors.append(f"{tag}: missing entry_id")
        elif entry.entry_id in seen_entry_ids:
            errors.append(f"{tag}: duplicate entry_id")
        seen_entry_ids.add(entry.entry_id)

        if entry.test_id not in registry:
            errors.append(f"{tag}: test_id is not in the master registry")
        s_classes = classify_stop_ship(entry.test_id)
        if s_classes:
            errors.append(
                f"{tag}: REJECTED -- test is stop-ship {sorted(s_classes)}; "
                "S1-S4 have no exceptions process at all"
            )
        for fname in ("reason", "risk", "compensating_control", "blast_radius"):
            if not getattr(entry, fname, "").strip():
                errors.append(f"{tag}: missing {fname}")
        if not entry.approver_name.strip():
            errors.append(f"{tag}: missing approver_name")
        if not entry.reviewer_name.strip():
            errors.append(f"{tag}: missing reviewer_name")
        elif entry.reviewer_name.strip() == entry.approver_name.strip():
            errors.append(f"{tag}: reviewer must differ from approver (self-approval)")
        if not entry.reviewer_signature_present:
            errors.append(f"{tag}: reviewer signature missing")
        if not entry.disclosed_in_release_notes:
            errors.append(f"{tag}: release-notes disclosure missing (f17 P-20)")

        granted = _parse_date(entry.granted, errors, tag + " granted")
        expiry = _parse_date(entry.expiry, errors, tag + " expiry")
        if granted is not None and granted > today:
            errors.append(f"{tag}: granted date is in the future")
        if granted is not None and expiry is not None:
            if expiry <= granted:
                errors.append(f"{tag}: expiry must be after grant")
            if (expiry - granted).days > MAX_EXCEPTION_DAYS:
                errors.append(
                    f"{tag}: expiry is {(expiry - granted).days} days after grant; "
                    f"max is {MAX_EXCEPTION_DAYS}"
                )
            if expiry < today:
                errors.append(f"{tag}: EXPIRED on {entry.expiry}; an expired entry excuses nothing")
        if entry.renewal_count < 0:
            errors.append(f"{tag}: negative renewal_count")
        if entry.renewal_count > 1:
            errors.append(f"{tag}: second renewal rejected (max one renewal per test)")
        by_test.setdefault(entry.test_id, []).append(entry)

    for test_id, group in by_test.items():
        if len(group) > MAX_ENTRIES_PER_TEST:
            errors.append(
                f"test {test_id!r}: {len(group)} exception entries; "
                "max is 2 (initial + one renewal)"
            )
        elif len(group) == 2:
            initials = [e for e in group if e.renewal_count == 0]
            renewals = [e for e in group if e.renewal_count == 1]
            if len(initials) != 1 or len(renewals) != 1:
                errors.append(
                    f"test {test_id!r}: two entries must be exactly one initial "
                    "(renewal_count 0) and one renewal (renewal_count 1); "
                    "a 'new' entry for a test that already has one is a renewal"
                )
            elif renewals[0].renewal_of != initials[0].entry_id:
                errors.append(
                    f"test {test_id!r}: renewal must name renewal_of="
                    f"{initials[0].entry_id!r}"
                )
        elif len(group) == 1 and group[0].renewal_count != 0:
            errors.append(
                f"test {test_id!r}: single entry with renewal_count "
                f"{group[0].renewal_count} has no initial entry to renew"
            )
    return errors


def load_exception_registry(path) -> tuple:
    """Load a JSON exception registry file.

    Returns (entries, errors). A missing or malformed file is an
    ERROR, not an empty registry (f17 P-02: the release job fails if
    the registry file itself is malformed or missing). Callers that
    merely want "no exceptions" pass an empty list to
    :func:`validate_exception_registry` instead of calling this.
    """
    path = Path(path)
    if not path.exists():
        return [], [f"exception registry file missing: {path}"]
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (ValueError, OSError) as exc:
        return [], [f"exception registry file malformed: {path}: {exc}"]
    if not isinstance(data, list):
        return [], [f"exception registry file malformed: {path}: top level is not a list"]
    entries: list = []
    errors: list = []
    for i, item in enumerate(data):
        if not isinstance(item, dict):
            errors.append(f"exception registry entry {i} is not an object")
            continue
        try:
            entries.append(ExceptionEntry.from_dict(item))
        except (ValueError, TypeError) as exc:
            errors.append(f"exception registry entry {i} unreadable: {exc}")
    return entries, errors


# ---------------------------------------------------------------------------
# Artifact binding
# ---------------------------------------------------------------------------

@dataclass
class GateArtifact:
    """One gate artifact's binding to the artifact it gates.

    ``commit`` is the tested commit hash (never invented: use
    :func:`detect_commit`, which returns None when no repo exists).
    ``build_hash`` is the tested build's hash with ``build_hash_kind``
    saying what was hashed ('pyz' for dist/keyholder.pyz, 'source'
    for the source tree). ``verdict`` must be 'pass'.
    """

    commit: str
    build_hash: str
    build_hash_kind: str
    verdict: str
    counts: dict = field(default_factory=dict)

    def to_json(self) -> str:
        return json.dumps(
            {
                "commit": self.commit,
                "build_hash": self.build_hash,
                "build_hash_kind": self.build_hash_kind,
                "verdict": self.verdict,
                "counts": self.counts,
            },
            sort_keys=True,
        )

    @classmethod
    def from_json(cls, text: str) -> "GateArtifact":
        data = json.loads(text)
        return cls(
            commit=str(data["commit"]),
            build_hash=str(data["build_hash"]),
            build_hash_kind=str(data.get("build_hash_kind", "")),
            verdict=str(data["verdict"]),
            counts=dict(data.get("counts", {})),
        )


def detect_commit(root: Path | None = None) -> str | None:
    """Return the HEAD commit hash of a repo at ``root``, else None.

    No repo, no git, or any git failure -> None. Callers must treat
    None as UNBOUND and refuse the release; inventing a hash here
    would defeat the whole binding (f17 P-06).
    """
    root = Path(root) if root is not None else BUILD_ROOT
    if not (root / ".git").exists():
        return None
    try:
        out = subprocess.run(
            ["git", "rev-parse", "HEAD"],
            cwd=str(root),
            capture_output=True,
            text=True,
            timeout=30,
        )
    except (OSError, subprocess.TimeoutExpired):
        return None
    if out.returncode != 0:
        return None
    commit = out.stdout.strip()
    return commit if re.fullmatch(r"[0-9a-f]{40}", commit) else None


def compute_build_hash(root: Path | None = None) -> tuple:
    """Hash the shipped build. Returns (hexdigest, kind).

    If ``dist/keyholder.pyz`` exists it is the shipped artifact and
    its SHA-256 is the build hash (kind 'pyz'). Otherwise the hash
    covers the source tree (``keyholder/*.py`` + ``packs/*.json``,
    excluding ``__pycache__``) so a source-only gate artifact is
    still bound to exact bytes, not a filename (kind 'source').
    """
    root = Path(root) if root is not None else BUILD_ROOT
    pyz = root / "dist" / "keyholder.pyz"
    if pyz.exists():
        return hashlib.sha256(pyz.read_bytes()).hexdigest(), "pyz"
    digest = hashlib.sha256()
    files = sorted(
        [p for p in (root / "keyholder").rglob("*.py") if "__pycache__" not in p.parts]
        + [p for p in (root / "packs").glob("*.json")]
    )
    for path in files:
        digest.update(path.relative_to(root).as_posix().encode())
        digest.update(b"\0")
        digest.update(path.read_bytes())
        digest.update(b"\0")
    return digest.hexdigest(), "source"


def verify_gate_artifact(artifact, expected_commit, expected_build_hash,
                         expected_kind: str | None = None) -> list:
    """Verify one gate artifact against the artifact being shipped."""
    errors: list = []
    if artifact is None:
        return ["gate artifact MISSING: no evidence about this artifact, gate fails"]
    if artifact.verdict != "pass":
        errors.append(f"gate artifact verdict is {artifact.verdict!r}, not 'pass'")
    if expected_commit is None:
        errors.append(
            "gate artifact UNBOUND: expected commit is unknown (no repo); "
            "a release cannot be signed on unbound evidence"
        )
    elif artifact.commit != expected_commit:
        errors.append(
            f"gate artifact commit {artifact.commit!r} != shipped commit "
            f"{expected_commit!r}: evidence is about a different commit"
        )
    if expected_build_hash is None:
        errors.append("gate artifact UNBOUND: expected build hash is unknown")
    elif artifact.build_hash != expected_build_hash:
        errors.append(
            "gate artifact build hash != shipped build hash: evidence is "
            "about a different build"
        )
    if expected_kind is not None and artifact.build_hash_kind != expected_kind:
        errors.append(
            f"gate artifact build kind {artifact.build_hash_kind!r} != "
            f"expected {expected_kind!r}"
        )
    return errors


# ---------------------------------------------------------------------------
# Release-gate evaluation (the assertion the release job must make)
# ---------------------------------------------------------------------------

@dataclass
class GateResult:
    ok: bool
    errors: list
    counts: dict
    missing: list  # registry IDs with no discovered test (deletion)
    extra: list  # discovered IDs with no registry entry (unregistered)
    excused_skips: list
    unexcused_skips: list

    def report(self) -> str:
        lines = [f"release gate: {'PASS' if self.ok else 'FAIL'}", f"counts: {self.counts}"]
        if self.missing:
            lines.append(f"deleted from suite (registry IDs not discovered): {self.missing}")
        if self.extra:
            lines.append(f"unregistered tests (discovered, not in registry): {self.extra}")
        if self.unexcused_skips:
            lines.append(f"unexcused skipped/muted tests: {self.unexcused_skips}")
        if self.excused_skips:
            lines.append(f"excused skipped/muted tests (valid exception): {self.excused_skips}")
        for error in self.errors:
            lines.append(f"  - {error}")
        return "\n".join(lines)


def _result_ids(entries):
    """Extract test IDs from unittest result lists.

    failures/errors/skipped/expectedFailures hold (test, ...) tuples;
    unexpectedSuccesses holds bare test objects.
    """
    ids = set()
    for item in entries:
        test = item[0] if isinstance(item, tuple) else item
        ids.add(test.id())
    return ids


def outcomes_from_result(result) -> dict:
    """Split a unittest TestResult into outcome ID sets."""
    failed = _result_ids(result.failures)
    errored = _result_ids(result.errors)
    skipped = _result_ids(result.skipped)
    expected = _result_ids(result.expectedFailures)
    unexpected = _result_ids(result.unexpectedSuccesses)
    accounted = failed | errored | skipped | expected | unexpected
    # testsRun is a count, not IDs; passed IDs are recovered by the
    # caller via discovered-minus-accounted (see evaluate_release_gate).
    return {
        "failed": failed,
        "errored": errored,
        "skipped": skipped,
        "muted": expected | unexpected,
        "accounted": accounted,
        "tests_run": getattr(result, "testsRun", None),
    }


def evaluate_release_gate(*, discovered, outcomes, exceptions=(),
                          artifact=None, expected_commit=None,
                          expected_build_hash=None, expected_kind=None,
                          today: date | None = None) -> GateResult:
    """The release-job assertion (f17 P-05/P-06/P-07).

    ``discovered``: IDs the test runner actually discovered.
    ``outcomes``: dict with keys 'passed', 'failed', 'errored',
    'skipped', 'muted', each a set/list of IDs. 'passed' may be
    omitted, in which case it is derived as
    discovered - failed - errored - skipped - muted.
    ``exceptions``: ExceptionEntry list (already loaded).
    Returns a GateResult; ``ok`` is False unless EVERY check passes.
    A runner exit code of 0 is never consulted here -- only counts.
    """
    if today is None:
        today = date.today()
    errors: list = []
    discovered_set = set(discovered)
    registry_set = set(REGISTRY_IDS)

    missing = sorted(registry_set - discovered_set)
    extra = sorted(discovered_set - registry_set)
    if missing:
        errors.append(f"registry IDs deleted from suite: {missing}")
    if extra:
        errors.append(f"unregistered tests discovered (registry update required): {extra}")

    passed = set(outcomes.get("passed", ()))
    if not passed and "passed" not in outcomes:
        passed = discovered_set - set(outcomes.get("failed", ())) \
            - set(outcomes.get("errored", ())) \
            - set(outcomes.get("skipped", ())) - set(outcomes.get("muted", ()))
    failed = set(outcomes.get("failed", ()))
    errored = set(outcomes.get("errored", ()))
    skipped = set(outcomes.get("skipped", ()))
    muted = set(outcomes.get("muted", ()))
    executed = passed | failed | errored | skipped | muted

    # Executed == registry count, and every registry ID has exactly
    # one outcome. This is the assertion the release job must make.
    if len(executed) != len(registry_set):
        errors.append(
            f"executed count {len(executed)} != registry count {len(registry_set)}"
        )
    unaccounted = sorted(registry_set - executed)
    if unaccounted:
        errors.append(f"registry tests with no outcome (never ran): {unaccounted}")
    unknown_outcomes = sorted(executed - registry_set)
    if unknown_outcomes:
        errors.append(f"outcomes for unregistered tests: {unknown_outcomes}")

    if failed:
        errors.append(f"failing tests (never exceptable): {sorted(failed)}")
    if errored:
        errors.append(f"errored tests (never exceptable): {sorted(errored)}")

    exc_errors = validate_exception_registry(list(exceptions), today=today)
    errors.extend(exc_errors)
    excused_ids = set()
    if not exc_errors:
        # Only a fully valid registry may excuse anything, and only
        # skips/mutes -- never failures or errors (checked above).
        excused_ids = {e.test_id for e in exceptions}
    skipped_or_muted = skipped | muted
    excused_skips = sorted(skipped_or_muted & excused_ids)
    unexcused_skips = sorted(skipped_or_muted - excused_ids)
    if unexcused_skips:
        errors.append(
            f"skipped/muted tests without a valid exception "
            f"(a skip counts as a failure): {unexcused_skips}"
        )
    # An exception entry for a test that ran green is stale, not
    # fatal on its own, but it is reported so it cannot linger.
    stale = sorted(excused_ids & passed)
    if stale:
        errors.append(f"exception entries for tests that passed (stale, remove): {stale}")

    errors.extend(
        verify_gate_artifact(artifact, expected_commit, expected_build_hash,
                             expected_kind)
    )

    counts = {
        "registry": len(registry_set),
        "discovered": len(discovered_set),
        "executed": len(executed),
        "passed": len(passed),
        "failed": len(failed),
        "errored": len(errored),
        "skipped": len(skipped),
        "muted": len(muted),
        "excused_skips": len(excused_skips),
    }
    return GateResult(
        ok=not errors,
        errors=errors,
        counts=counts,
        missing=missing,
        extra=extra,
        excused_skips=excused_skips,
        unexcused_skips=unexcused_skips,
    )


# ---------------------------------------------------------------------------
# Discovery + regeneration
# ---------------------------------------------------------------------------

def discover_test_ids(tests_dir: Path | None = None,
                      build_root: Path | None = None):
    """Discover test IDs without running any test.

    Returns (ids, import_failures). Importing a test module is not
    running it; a module that fails to import is reported, never
    silently dropped (a dropped module is a vacuous suite).
    """
    import unittest

    tests_dir = Path(tests_dir) if tests_dir is not None else TESTS_DIR
    build_root = Path(build_root) if build_root is not None else BUILD_ROOT
    for path in (str(tests_dir), str(build_root)):
        if path not in sys.path:
            sys.path.insert(0, path)
    loader = unittest.TestLoader()
    ids: list = []
    failures: list = []

    def walk(suite):
        for item in suite:
            if isinstance(item, unittest.TestSuite):
                yield from walk(item)
            else:
                yield item

    for test_file in sorted(tests_dir.glob("test_*.py")):
        stem = test_file.stem
        spec = importlib.util.spec_from_file_location(stem, test_file)
        if spec is None or spec.loader is None:
            failures.append(f"{stem}: cannot build import spec")
            continue
        module = importlib.util.module_from_spec(spec)
        sys.modules[stem] = module
        try:
            spec.loader.exec_module(module)
        except Exception as exc:  # noqa: BLE001 -- reported, not hidden
            failures.append(f"{stem}: import failed: {type(exc).__name__}: {exc}")
            continue
        try:
            suite = loader.loadTestsFromModule(module)
        except Exception as exc:  # noqa: BLE001
            failures.append(f"{stem}: load failed: {type(exc).__name__}: {exc}")
            continue
        for test in walk(suite):
            ids.append(test.id())
    return sorted(set(ids)), failures


def regenerate_registry() -> int:
    """Rewrite the REGISTRY_IDS block in this file from discovery."""
    ids, failures = discover_test_ids()
    if failures:
        raise SystemExit(f"refusing to regenerate: import failures: {failures}")
    text = Path(__file__).read_text(encoding="utf-8")
    block = "REGISTRY_IDS = (\n" + "".join(f"    {i!r},\n" for i in ids) + ")"
    new_text, count = re.subn(
        r"REGISTRY_IDS = \(.*?\)",
        lambda _: block,
        text,
        count=1,
        flags=re.DOTALL,
    )
    if count != 1:
        raise SystemExit("regeneration failed: REGISTRY_IDS block not found")
    Path(__file__).write_text(new_text, encoding="utf-8")
    return len(ids)


def main(argv) -> int:
    if "--dump" in argv:
        ids, failures = discover_test_ids()
        for test_id in ids:
            print(test_id)
        print(f"# {len(ids)} discovered, {len(failures)} import failures", file=sys.stderr)
        for failure in failures:
            print(f"# {failure}", file=sys.stderr)
        return 1 if failures else 0
    if "--regenerate" in argv:
        count = regenerate_registry()
        print(f"registry regenerated: {count} tests")
        return 0
    print(__doc__)
    print("usage: python3 tests/test_registry.py [--dump | --regenerate]")
    return 2


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))


# ---------------------------------------------------------------------------
# Registry self-tests (small: the gate behaviour tests live in
# tests/test_gates.py; these only guard the registry's own shape)
# ---------------------------------------------------------------------------

import unittest  # noqa: E402


class TestRegistryShape(unittest.TestCase):
    def test_registry_nonempty_sorted_unique(self):
        self.assertGreater(len(REGISTRY_IDS), 0)
        self.assertEqual(list(REGISTRY_IDS), sorted(REGISTRY_IDS))
        self.assertEqual(len(REGISTRY_IDS), len(set(REGISTRY_IDS)))

    def test_registry_ids_well_formed(self):
        for test_id in REGISTRY_IDS:
            parts = test_id.split(".")
            self.assertGreaterEqual(len(parts), 3, test_id)
            self.assertTrue(test_id.startswith("test_"), test_id)

    def test_stop_ship_set_is_a_real_subset(self):
        s_ids = stop_ship_ids()
        self.assertGreater(len(s_ids), 0)
        self.assertLess(len(s_ids), len(REGISTRY_IDS))
        self.assertTrue(s_ids <= set(REGISTRY_IDS))
